CREATE TABLE maintenance_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), device_id uuid NOT NULL, user_id varchar(64) NOT NULL DEFAULT auth.uid(), title varchar(64) NOT NULL, type varchar(16) NOT NULL, occurred_at date NOT NULL, cost_cents integer, vendor varchar(128), notes varchar(1000), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());